async function loadHaSettings(){try{const e=await fetch("/api/settings/ha");if(e.ok){const t=await e.json();document.getElementById("ha-activate").checked=t.activate,document.getElementById("ha-ip").value=t.ip||"",document.getElementById("ha-port").value=t.port||"",document.getElementById("ha-user").value=t.user||"",document.getElementById("ha-pass").value=t.pass||"";const n=document.getElementById("ha-activate"),o=document.getElementById("form-ha-connection");n.checked?o.style.display="block":o.style.display="none",n.addEventListener("change",(function(){this.checked?o.style.display="block":o.style.display="none"}))}else console.error("Failed to load ha settings")}catch(e){console.error("Error fetching ha settings:",e)}}async function saveHaSettings(){const e=document.getElementById("ha-activate").checked,t=document.getElementById("ha-ip").value,n=document.getElementById("ha-port").value,o=document.getElementById("ha-user").value,s=document.getElementById("ha-pass").value,a=new URLSearchParams;a.append("ip",t),a.append("port",n),a.append("user",o),a.append("pass",s),a.append("activate",e);try{if((await fetch("/api/settings/ha",{method:"POST",headers:{"Content-Type":"application/x-www-form-urlencoded"},body:a.toString()})).ok){const e=document.getElementById("alert-saved-ha-settings");e.style.display="block",setTimeout((()=>{e.style.display="none"}),3e3)}else console.error("Failed to save ha settings")}catch(e){console.error("Error saving ha settings:",e)}}async function showTestConnectionModal(){document.getElementById("modal-test-connection-testing").style.display="block",document.getElementById("modal-test-connection-success").style.display="none",document.getElementById("modal-test-connection-fail").style.display="none";new bootstrap.Modal(document.getElementById("modal-test-connection")).show();try{const e=await fetch("/api/test/ha");if(e.ok){const t=await e.json();document.getElementById("modal-test-connection-testing").style.display="none","success"===t.status?(document.getElementById("modal-test-connection-success").style.display="block",document.getElementById("modal-test-connection-fail").style.display="none"):(document.getElementById("modal-test-connection-success").style.display="none",document.getElementById("modal-test-connection-fail").style.display="block")}else console.error("Failed to connect to ha")}catch(e){console.error("Error calling API:",e)}}document.getElementById("btn-modal-test-connection-close").addEventListener("click",(function(){bootstrap.Modal.getInstance(document.getElementById("modal-test-connection")).hide()})),document.getElementById("ha-save").addEventListener("click",(function(e){e.preventDefault(),saveHaSettings()})),document.getElementById("btn-connection-test").addEventListener("click",(function(){showTestConnectionModal()})),window.onload=function(){loadHaSettings(),document.getElementById("alert-saved-ha-settings").style.display="none",document.getElementById("modal-test-connection-success").style.display="none",document.getElementById("modal-test-connection-fail").style.display="none"};